          rationale: hit.rationale,
        });
      }
      cached++;
      return;
    }

    const t0 = Date.now();
    try {
      const res = await generateObject({
        model: column.model,
        schema: z.object({
          value: valueSchema(column.output_spec),
          rationale: z.string(),
        }),
        system: systemFor(column.output_spec),
        prompt: text,
        temperature: CELL_DECODE.temperature,
      });
      const cellIn = res.usage.inputTokens ?? 0;
      const cellOut = res.usage.outputTokens ?? 0;
      const cellCost = (cellIn * price.in + cellOut * price.out) / 1e6;
      inTok += cellIn;
      outTok += cellOut;
      costUsd += cellCost;
      await writeCell({
        columnId: column.id,
        rowId,
        promptVersion: column.prompt_version,
        model: column.model,
        contentHash,
        status: "done",
        value: res.object.value,
        rationale: res.object.rationale.slice(0, 500),
        inputTokens: cellIn,
        outputTokens: cellOut,
        costUsd: cellCost,
        latencyMs: Date.now() - t0,
      });
      ran++;
    } catch (err) {
      errors++;
      await writeCell({
        columnId: column.id,
        rowId,
        promptVersion: column.prompt_version,
        model: column.model,
        contentHash,
        status: "error",
        error: err instanceof Error ? err.message.slice(0, 800) : String(err),
        latencyMs: Date.now() - t0,
      });
    }
  });

  await recordLedger({
    kind: "run",
    columnId: column.id,
    model: column.model,
    cells: ran,
    inputTokens: inTok,
    outputTokens: outTok,
    costUsd,
  });

  return {
    ran,
    cached,
    skipped: 0,
    errors,
    costUsd,
    ms: Date.now() - started,
  };
}
